import { Plus, Minus, Info, AlertCircle } from "lucide-react";
import { Product, ForecastResult } from "@/types";

interface ProductRowProps {
  product: Product;
  forecast: ForecastResult;
  isSelected: boolean;
  onSelect: () => void;
  onQuantityChange: (quantity: number) => void;
  currentCartQuantity: number;
}

const categoryColors: Record<string, string> = {
  "肉类": "bg-red-100 text-red-700",
  "水产": "bg-blue-100 text-blue-700",
  "鲜禽": "bg-orange-100 text-orange-700",
  "蔬菜": "bg-green-100 text-green-700",
  "水果": "bg-yellow-100 text-yellow-700",
};

function getStockLevel(stock: number, baseline: number): "critical" | "warning" | "safe" {
  const ratio = stock / baseline;
  if (ratio < 0.3) return "critical";
  if (ratio < 0.6) return "warning";
  return "safe";
}

export default function ProductRow({
  product,
  forecast,
  isSelected,
  onSelect,
  onQuantityChange,
  currentCartQuantity,
}: ProductRowProps) {
  const stockLevel = getStockLevel(product.currentStock, forecast.baseline);
  const hasOrder = forecast.finalOrder > 0;
  const quantity = currentCartQuantity || forecast.finalOrder;

  const stockColor = {
    critical: "bg-ember-500",
    warning: "bg-yellow-400",
    safe: "bg-forest-400",
  }[stockLevel];

  const stockText = {
    critical: "库存紧张",
    warning: "库存偏低",
    safe: "库存充足",
  }[stockLevel];

  return (
    <div
      className={`bg-white rounded-xl p-5 shadow-card hover:shadow-cardHover transition-all duration-300 cursor-pointer ${
        isSelected ? "ring-2 ring-forest-400" : ""
      }`}
      onClick={onSelect}
    >
      <div className="flex items-center gap-4">
        <div className={`flex-shrink-0 w-10 h-10 ${categoryColors[product.category]} rounded-lg flex items-center justify-center font-bold text-sm`}>
          {product.category[0]}
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h4 className="font-medium text-ink truncate">{product.name}</h4>
            {stockLevel === "critical" && (
              <AlertCircle className="w-4 h-4 text-ember-500 flex-shrink-0" />
            )}
          </div>
          <div className="flex items-center gap-3 mt-1 text-xs text-gray-500">
            <span>{product.supplierId}</span>
            <span>·</span>
            <span>MOQ: {product.moq}{product.unit}</span>
            <span>·</span>
            <span>包装: {product.packSize}{product.unit}</span>
          </div>
        </div>

        <div className="flex-shrink-0 w-32">
          <div className="flex items-center justify-between text-xs mb-1">
            <span className="text-gray-500">当前库存</span>
            <span className={`font-medium ${stockLevel === "critical" ? "text-ember-500" : stockLevel === "warning" ? "text-yellow-600" : "text-forest-600"}`}>
              {product.currentStock} {product.unit}
            </span>
          </div>
          <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
            <div
              className={`h-full ${stockColor} rounded-full transition-all duration-500`}
              style={{ width: `${Math.min(100, (product.currentStock / forecast.baseline) * 100)}%` }}
            />
          </div>
          <p className={`text-xs mt-1 text-right ${
            stockLevel === "critical" ? "text-ember-500" : "text-gray-500"
          }`}>
            {stockText}
          </p>
        </div>

        <div className="flex-shrink-0 w-36 text-center">
          <p className="text-xs text-gray-500 mb-1">预测销量</p>
          <p className="text-xl font-bold text-ink num">{forecast.prediction}</p>
          <p className="text-xs text-gray-400">{product.unit}/日</p>
        </div>

        {hasOrder && (
          <div className="flex-shrink-0 w-40">
            <p className="text-xs text-gray-500 mb-1">建议订货</p>
            <div className="flex items-center justify-center gap-2">
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  if (quantity > product.moq) {
                    onQuantityChange(Math.max(product.moq, quantity - product.packSize));
                  }
                }}
                className="w-8 h-8 rounded-full bg-gray-100 hover:bg-gray-200 flex items-center justify-center transition-all btn-press"
                disabled={quantity <= product.moq}
              >
                <Minus className="w-4 h-4 text-gray-600" />
              </button>
              <span className="text-2xl font-display font-bold text-forest-700 num w-12 text-center animate-numberPop">
                {quantity}
              </span>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onQuantityChange(quantity + product.packSize);
                }}
                className="w-8 h-8 rounded-full bg-forest-100 hover:bg-forest-200 flex items-center justify-center transition-all btn-press"
              >
                <Plus className="w-4 h-4 text-forest-700" />
              </button>
            </div>
            <p className="text-xs text-gray-400 mt-1 text-center">{product.unit}</p>
          </div>
        )}

        <button
          onClick={(e) => {
            e.stopPropagation();
            onSelect();
          }}
          className="flex-shrink-0 w-10 h-10 rounded-full bg-forest-50 hover:bg-forest-100 flex items-center justify-center transition-colors"
          title="查看预测归因"
        >
          <Info className="w-5 h-5 text-forest-600" />
        </button>
      </div>
    </div>
  );
}
