import { useEffect, useRef } from "react";
import ReactEChartsCore from "echarts-for-react/lib/core";
import * as echarts from "echarts/core";
import { LineChart, BarChart, PieChart } from "echarts/charts";
import { GridComponent, TooltipComponent, LegendComponent } from "echarts/components";
import { CanvasRenderer } from "echarts/renderers";
import { TrendingDown, BarChart3, PieChart as PieIcon, AlertTriangle } from "lucide-react";
import { getLossTrend30d, getLossTotalByCategory, getLossByReason, products } from "@/lib/mockData";

echarts.use([LineChart, BarChart, PieChart, GridComponent, TooltipComponent, LegendComponent, CanvasRenderer]);

export default function LossDashboard() {
  const chartRef = useRef(null);

  useEffect(() => {
    return () => {
      if (chartRef.current) {
        const chart = echarts.getInstanceByDom(chartRef.current);
        if (chart) chart.dispose();
      }
    };
  }, []);

  const trendData = getLossTrend30d();
  const categoryLoss = getLossTotalByCategory();
  const reasonLoss = getLossByReason();

  const lineOption: echarts.EChartsCoreOption = {
    tooltip: { trigger: "axis", formatter: "{b}<br/>损耗率: {c}%" },
    grid: { left: "3%", right: "4%", bottom: "3%", containLabel: true },
    xAxis: {
      type: "category",
      data: trendData.map(d => d.date.slice(5)),
      axisLine: { lineStyle: { color: "#E8E5DC" } },
      axisLabel: { color: "#6B7280", fontSize: 11 },
    },
    yAxis: {
      type: "value",
      axisLine: { lineStyle: { color: "#E8E5DC" } },
      axisLabel: { color: "#6B7280", formatter: "{value}%" },
      splitLine: { lineStyle: { color: "#F3F4F6" } },
    },
    series: [{
      name: "损耗率",
      type: "line",
      smooth: true,
      data: trendData.map(d => d.rate),
      lineStyle: { color: "#FF7A45", width: 2 },
      areaStyle: {
        color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
          { offset: 0, color: "rgba(255, 122, 69, 0.25)" },
          { offset: 1, color: "rgba(255, 122, 69, 0)" },
        ]),
      },
      symbol: "circle",
      symbolSize: 4,
      itemStyle: { color: "#FF7A45" },
    }],
  };

  const barOption: echarts.EChartsCoreOption = {
    tooltip: { trigger: "axis", axisPointer: { type: "shadow" }, formatter: "{b}<br/>损耗金额: ¥{c}" },
    grid: { left: "3%", right: "4%", bottom: "3%", containLabel: true },
    xAxis: {
      type: "value",
      axisLine: { lineStyle: { color: "#E8E5DC" } },
      axisLabel: { color: "#6B7280", formatter: "¥{value}" },
      splitLine: { lineStyle: { color: "#F3F4F6" } },
    },
    yAxis: {
      type: "category",
      data: Object.keys(categoryLoss),
      axisLine: { lineStyle: { color: "#E8E5DC" } },
      axisLabel: { color: "#1A1F1C" },
    },
    series: [{
      type: "bar",
      data: Object.values(categoryLoss).map(v => Math.round(v)),
      itemStyle: {
        borderRadius: [0, 4, 4, 0],
        color: new echarts.graphic.LinearGradient(0, 0, 1, 0, [
          { offset: 0, color: "#0F3D2E" },
          { offset: 1, color: "#3DBE7A" },
        ]),
      },
      barWidth: "60%",
    }],
  };

  const pieOption: echarts.EChartsCoreOption = {
    tooltip: { trigger: "item", formatter: "{b}: {c}元 ({d}%)" },
    legend: {
      orient: "vertical",
      right: "5%",
      top: "center",
      textStyle: { color: "#6B7280" },
    },
    series: [{
      type: "pie",
      radius: ["40%", "70%"],
      center: ["40%", "50%"],
      avoidLabelOverlap: false,
      itemStyle: {
        borderRadius: 8,
        borderColor: "#F7F4EC",
        borderWidth: 2,
      },
      label: { show: false },
      emphasis: { label: { show: true, fontSize: 14, fontWeight: "bold" } },
      labelLine: { show: false },
      data: Object.entries(reasonLoss).map(([name, value], i) => ({
        value: Math.round(value),
        name,
        itemStyle: { color: ["#FF7A45", "#F59E0B", "#3DBE7A", "#6366F1"][i] },
      })),
    }],
  };

  const totalLoss = Object.values(categoryLoss).reduce((sum, v) => sum + v, 0);
  const avgLossRate = trendData.length > 0
    ? trendData.reduce((sum, d) => sum + d.rate, 0) / trendData.length
    : 0;

  return (
    <div className="min-h-screen bg-cream">
      <div className="mb-6">
        <h2 className="font-display text-2xl font-bold text-ink mb-2">损耗复盘</h2>
        <p className="text-gray-500">近30天损耗数据分析与归因</p>
      </div>

      <div className="grid grid-cols-3 gap-4 mb-6">
        <div className="bg-white rounded-xl p-5 shadow-card">
          <div className="flex items-center justify-between mb-3">
            <TrendingDown className="w-5 h-5 text-ember-500" />
            <span className="text-xs text-gray-500">近30天</span>
          </div>
          <div className="flex items-baseline gap-1">
            <span className="text-3xl font-display font-bold text-ember-600 num">¥{totalLoss.toFixed(0)}</span>
          </div>
          <p className="text-sm text-gray-500 mt-1">总损耗金额</p>
        </div>

        <div className="bg-white rounded-xl p-5 shadow-card">
          <div className="flex items-center justify-between mb-3">
            <BarChart3 className="w-5 h-5 text-forest-500" />
            <span className="text-xs text-gray-500">平均</span>
          </div>
          <div className="flex items-baseline gap-1">
            <span className="text-3xl font-display font-bold text-forest-700 num">{avgLossRate.toFixed(1)}</span>
            <span className="text-sm text-gray-500">%</span>
          </div>
          <p className="text-sm text-gray-500 mt-1">平均损耗率</p>
        </div>

        <div className="bg-white rounded-xl p-5 shadow-card">
          <div className="flex items-center justify-between mb-3">
            <AlertTriangle className="w-5 h-5 text-yellow-500" />
            <span className="text-xs text-gray-500">最高品类</span>
          </div>
          <div className="flex items-baseline gap-1">
            <span className="text-3xl font-display font-bold text-yellow-600">
              {Object.keys(categoryLoss).sort((a, b) => categoryLoss[b] - categoryLoss[a])[0] || "-"}
            </span>
          </div>
          <p className="text-sm text-gray-500 mt-1">损耗最高品类</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-6 mb-6">
        <div className="bg-white rounded-xl p-6 shadow-card">
          <h3 className="font-display text-lg font-bold text-ink mb-4 flex items-center gap-2">
            <TrendingDown className="w-5 h-5 text-ember-500" />
            损耗率趋势（近30天）
          </h3>
          <div ref={chartRef} className="h-64">
            <ReactEChartsCore echarts={echarts} option={lineOption} style={{ height: "100%" }} />
          </div>
        </div>

        <div className="bg-white rounded-xl p-6 shadow-card">
          <h3 className="font-display text-lg font-bold text-ink mb-4 flex items-center gap-2">
            <BarChart3 className="w-5 h-5 text-forest-500" />
            品类损耗排行
          </h3>
          <div className="h-64">
            <ReactEChartsCore echarts={echarts} option={barOption} style={{ height: "100%" }} />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-6">
        <div className="bg-white rounded-xl p-6 shadow-card">
          <h3 className="font-display text-lg font-bold text-ink mb-4 flex items-center gap-2">
            <PieIcon className="w-5 h-5 text-blue-500" />
            损耗原因分布
          </h3>
          <div className="h-64">
            <ReactEChartsCore echarts={echarts} option={pieOption} style={{ height: "100%" }} />
          </div>
        </div>

        <div className="bg-white rounded-xl p-6 shadow-card">
          <h3 className="font-display text-lg font-bold text-ink mb-4">损耗详情</h3>
          <div className="space-y-3">
            {products.map(product => {
              const productLoss = trendData.reduce((sum, d) => sum + d.rate, 0) / trendData.length * 0.01 * (product.price * 10);
              return (
                <div key={product.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                  <div className="flex items-center gap-3">
                    <span className={`w-8 h-8 rounded-lg flex items-center justify-center text-sm font-bold ${
                      product.category === "肉类" ? "bg-red-100 text-red-700" :
                      product.category === "水产" ? "bg-blue-100 text-blue-700" :
                      product.category === "鲜禽" ? "bg-orange-100 text-orange-700" :
                      product.category === "蔬菜" ? "bg-green-100 text-green-700" :
                      "bg-yellow-100 text-yellow-700"
                    }`}>
                      {product.category[0]}
                    </span>
                    <div>
                      <p className="font-medium text-ink text-sm">{product.name}</p>
                      <p className="text-xs text-gray-500">{product.category}</p>
                    </div>
                  </div>
                  <span className="font-bold text-ember-600 num">¥{productLoss.toFixed(0)}</span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}
