import { useOrderStore } from "@/store/useOrderStore";
import { Package, ShieldCheck, DollarSign, TrendingDown } from "lucide-react";

export default function KpiBar() {
  const { products, forecasts, cart } = useOrderStore();

  const needOrderCount = products.filter(p => forecasts[p.id]?.finalOrder > 0).length;
  
  const avgConfidence = products.length > 0
    ? products.reduce((sum, p) => sum + (forecasts[p.id]?.confidence || 0), 0) / products.length
    : 0;

  const totalOrderAmount = cart.reduce((sum, item) => {
    const product = products.find(p => p.id === item.productId);
    return sum + (product ? item.quantity * product.price : 0);
  }, 0);

  const avgLossRate = products.length > 0
    ? products.reduce((sum, p) => {
        const sales = p.currentStock + (forecasts[p.id]?.prediction || 0);
        return sum + ((forecasts[p.id]?.prediction || 0) * 0.05 / sales);
      }, 0) / products.length
    : 0;

  const kpis = [
    {
      icon: Package,
      label: "待订商品",
      value: needOrderCount,
      suffix: "个",
      color: "bg-forest-600",
      trend: "up",
    },
    {
      icon: ShieldCheck,
      label: "预测置信度",
      value: (avgConfidence * 100).toFixed(0),
      suffix: "%",
      color: "bg-forest-500",
      trend: "up",
    },
    {
      icon: DollarSign,
      label: "预计订货额",
      value: totalOrderAmount.toFixed(0),
      suffix: "元",
      color: "bg-forest-400",
      trend: "up",
    },
    {
      icon: TrendingDown,
      label: "预计损耗率",
      value: (avgLossRate * 100).toFixed(1),
      suffix: "%",
      color: "bg-ember-500",
      trend: "down",
    },
  ];

  return (
    <div className="grid grid-cols-4 gap-4 mb-6">
      {kpis.map((kpi, index) => {
        const Icon = kpi.icon;
        return (
          <div
            key={kpi.label}
            className={`${kpi.color} rounded-xl p-5 text-white shadow-card animate-fadeUp`}
            style={{ animationDelay: `${index * 80}ms` }}
          >
            <div className="flex items-center justify-between mb-3">
              <Icon className="w-5 h-5 opacity-80" />
              <span className="text-xs opacity-70">{kpi.label}</span>
            </div>
            <div className="flex items-baseline gap-1">
              <span className="text-3xl font-display font-bold num">{kpi.value}</span>
              <span className="text-sm opacity-70">{kpi.suffix}</span>
            </div>
            <div className="mt-2 h-1 bg-black/20 rounded-full overflow-hidden">
              <div
                className="h-full bg-white/30 rounded-full transition-all duration-500"
                style={{ width: `${Math.min(100, Number(kpi.value) || 70)}%` }}
              />
            </div>
          </div>
        );
      })}
    </div>
  );
}
