import { X, Check, Package } from "lucide-react";
import { Order } from "@/types";

interface OrderPreviewModalProps {
  orders: Order[];
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
}

export default function OrderPreviewModal({ orders, isOpen, onClose, onConfirm }: OrderPreviewModalProps) {
  if (!isOpen) return null;

  const totalAmount = orders.reduce((sum, o) => sum + o.totalAmount, 0);

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 animate-fadeIn">
      <div className="bg-white rounded-2xl w-full max-w-3xl max-h-[80vh] flex flex-col animate-scaleIn">
        <div className="flex items-center justify-between p-6 border-b border-gray-100">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-forest-100 rounded-xl flex items-center justify-center">
              <Package className="w-5 h-5 text-forest-700" />
            </div>
            <div>
              <h3 className="font-display text-xl font-bold text-ink">订单预览</h3>
              <p className="text-sm text-gray-500">{orders.length} 个供应商订单</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="w-9 h-9 rounded-full bg-gray-100 hover:bg-gray-200 flex items-center justify-center transition-colors"
          >
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {orders.map(order => (
            <div key={order.id} className="bg-gray-50 rounded-xl p-5">
              <div className="flex items-center justify-between mb-4">
                <div>
                  <h4 className="font-medium text-ink">{order.supplierName}</h4>
                  <p className="text-xs text-gray-500">订单号: {order.id}</p>
                </div>
                <span className="text-sm font-bold text-forest-700">¥{order.totalAmount.toFixed(2)}</span>
              </div>
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-gray-500">
                    <th className="text-left py-2 font-normal">商品</th>
                    <th className="text-right py-2 font-normal">单价</th>
                    <th className="text-right py-2 font-normal">数量</th>
                    <th className="text-right py-2 font-normal">小计</th>
                  </tr>
                </thead>
                <tbody>
                  {order.items.map(item => (
                    <tr key={item.productId} className="border-t border-gray-200">
                      <td className="py-3">
                        <span className="font-medium text-ink">{item.productName}</span>
                        <span className="text-gray-400 ml-2">({item.packSize}{item.unit}/包)</span>
                      </td>
                      <td className="py-3 text-right text-gray-600">¥{item.price.toFixed(2)}</td>
                      <td className="py-3 text-right font-medium text-ink">{item.quantity}{item.unit}</td>
                      <td className="py-3 text-right font-bold text-forest-700">¥{(item.quantity * item.price).toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ))}
        </div>

        <div className="p-6 border-t border-gray-100 bg-white">
          <div className="flex items-center justify-between mb-4">
            <span className="text-gray-600">订单总计</span>
            <span className="text-2xl font-display font-bold text-forest-700">¥{totalAmount.toFixed(2)}</span>
          </div>
          <div className="flex gap-3">
            <button
              onClick={onClose}
              className="flex-1 py-3 px-6 rounded-xl border-2 border-gray-200 text-gray-600 font-medium hover:bg-gray-50 transition-all btn-press"
            >
              取消
            </button>
            <button
              onClick={onConfirm}
              className="flex-1 py-3 px-6 rounded-xl bg-forest-800 text-white font-medium hover:bg-forest-700 transition-all flex items-center justify-center gap-2 shadow-lg shadow-forest-800/20 btn-press ripple"
            >
              <Check className="w-5 h-5" />
              确认生成订单
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
