import { X, ChevronRight, Info, TrendingUp } from "lucide-react";
import { useOrderStore } from "@/store/useOrderStore";
import { getSupplierById, getSalesRecordsByProductId } from "@/lib/mockData";

export default function AttributionDrawer() {
  const { selectedProductId, products, forecasts, setSelectedProductId } = useOrderStore();

  if (!selectedProductId) return null;

  const product = products.find(p => p.id === selectedProductId);
  const forecast = forecasts[selectedProductId];
  const supplier = product ? getSupplierById(product.supplierId) : null;
  const salesRecords = selectedProductId ? getSalesRecordsByProductId(selectedProductId) : [];

  if (!product || !forecast) return null;

  return (
    <div className="fixed inset-y-0 right-0 w-[480px] bg-white shadow-2xl z-50 flex flex-col animate-slideInRight">
      <div className="flex items-center justify-between p-5 border-b border-gray-100">
        <div className="animate-slideDown">
          <h3 className="font-display text-xl font-bold text-ink">{product.name}</h3>
          <p className="text-sm text-gray-500 mt-1">
            {product.category} · {product.unit} · 保质期 {product.shelfLife}天
          </p>
        </div>
        <button
          onClick={() => setSelectedProductId(null)}
          className="w-9 h-9 rounded-full bg-gray-100 hover:bg-gray-200 flex items-center justify-center transition-all btn-press"
        >
          <X className="w-5 h-5 text-gray-500" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-6">
        <div className="bg-gradient-to-br from-forest-50 to-forest-100 rounded-xl p-5">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm text-forest-600 font-medium">AI 建议订货量</span>
            <div className="flex items-center gap-2">
              <span className="text-xs px-2 py-1 bg-forest-400 text-white rounded-full">
                置信度 {(forecast.confidence * 100).toFixed(0)}%
              </span>
            </div>
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-4xl font-display font-bold text-forest-800 num">
              {forecast.finalOrder}
            </span>
            <span className="text-lg text-forest-600">{product.unit}</span>
          </div>
          <div className="mt-3 flex gap-4 text-sm text-forest-600">
            <div>当前库存: <span className="font-medium">{product.currentStock}{product.unit}</span></div>
            <div>MOQ: <span className="font-medium">{product.moq}{product.unit}</span></div>
            {supplier && (
              <div>配送: <span className="font-medium">{supplier.leadTime}</span></div>
            )}
          </div>
        </div>

        <div>
          <h4 className="font-display text-lg font-bold text-ink mb-4 flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-forest-500" />
            近7日销售数据
          </h4>
          <div className="bg-gray-50 rounded-xl p-4">
            <div className="flex items-end justify-between gap-2 h-32">
              {salesRecords.map((record, index) => {
                const maxQty = Math.max(...salesRecords.map(r => r.quantity));
                const heightPercent = (record.quantity / maxQty) * 100;
                return (
                  <div key={index} className="flex-1 flex flex-col items-center gap-1">
                    <div className="w-full flex flex-col items-center">
                      <span className="text-xs font-medium text-ink mb-1">{record.quantity}</span>
                      <div
                        className="w-full bg-forest-400 rounded-t-lg transition-all duration-500 hover:bg-forest-500"
                        style={{
                          height: `${Math.max(heightPercent, 10)}%`,
                          minHeight: "8px",
                        }}
                      />
                    </div>
                    <span className="text-xs text-gray-500">{record.date.slice(5)}</span>
                    <span className="text-xs text-gray-400">周{record.weekday}</span>
                  </div>
                );
              })}
            </div>
            <div className="mt-3 pt-3 border-t border-gray-200 flex items-center justify-between text-xs text-gray-500">
              <span>日均销量: <span className="font-bold text-forest-700">{forecast.baseline} {product.unit}</span></span>
              <span>总销量: <span className="font-bold text-forest-700">{salesRecords.reduce((sum, r) => sum + r.quantity, 0)} {product.unit}</span></span>
            </div>
          </div>
        </div>

        <div>
          <h4 className="font-display text-lg font-bold text-ink mb-4 flex items-center gap-2">
            <Info className="w-5 h-5 text-forest-500" />
            预测归因
          </h4>
          <div className="space-y-3">
            {forecast.attribution.map((step, index) => (
              <div
                key={index}
                className="flex items-center gap-3 bg-gray-50 rounded-lg p-4 hover:bg-gray-100 transition-colors animate-fadeUp"
                style={{ animationDelay: `${index * 100}ms` }}
              >
                <div className="flex-shrink-0 w-8 h-8 bg-forest-100 rounded-full flex items-center justify-center text-forest-700 font-bold text-sm">
                  {index + 1}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium text-ink">{step.label}</span>
                    {step.coefficient && (
                      <span className={`text-xs px-2 py-0.5 rounded-full ${
                        step.coefficient > 1 ? "bg-forest-100 text-forest-700" : 
                        step.coefficient < 1 ? "bg-ember-100 text-ember-600" : "bg-gray-100 text-gray-600"
                      }`}>
                        ×{step.coefficient}
                      </span>
                    )}
                  </div>
                  {step.note && (
                    <p className="text-xs text-gray-500 mt-1">{step.note}</p>
                  )}
                </div>
                <div className="flex-shrink-0 text-right">
                  <span className="text-lg font-bold text-forest-700 num">{step.value}</span>
                  {index < forecast.attribution.length - 1 && (
                    <ChevronRight className="w-4 h-4 text-gray-400 mx-auto mt-1" />
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-gray-50 rounded-xl p-4">
          <h4 className="text-sm font-medium text-gray-700 mb-3">计算公式</h4>
          <div className="text-xs text-gray-500 space-y-2 font-mono">
            <p>预测量 = 基线 × 周期权 × 天气系数 × 节假日系数 × (1+损耗率)</p>
            <p>安全库存 = 基线 × 0.2</p>
            <p>订货建议 = max(预测量 + 安全库存 - 当前库存, 0)</p>
            <p>最终订货 = ceil(建议/包装规格) × 包装规格 ≥ MOQ</p>
          </div>
        </div>
      </div>
    </div>
  );
}
